interface.definition:
a!localVariables(
  local!validOfficeVisitDates: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6445183"(
    returnCDT: true,
    isActive: true
  ),
  local!validDropdownMenuOptions: text(todate(index(local!validOfficeVisitDates, "officeVisitDate", "")), "dddd, MMMM d, yyyy"),
  local!dropdownMenuOptions: if(
    contains(local!validDropdownMenuOptions, ri!nomination.officeVisitAvailability),
    local!validDropdownMenuOptions,
    reject(fn!isnull, append(local!validDropdownMenuOptions, ri!nomination.officeVisitAvailability))
  ),
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    label: if(
      property(ri!nomination,"statusId",tointeger(null)) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458889",
      "Interview Availability",
      if(
        property(ri!nomination,"statusId",tointeger(null)) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458932",
        "Office Visit Availability",
        ""
      )
    ),
    showWhen: ri!showWhen,
    labelColor: "SECONDARY",
    contents: {
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        labelSize: "SMALL",
        marginBelow: "STANDARD",
        isCollapsible: true,
        contents: #"SYSTEM_SYSRULES_columnsLayout"(
          marginBelow: "STANDARD",
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  labelPosition: "COLLAPSED",
                  value: {
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: {"Please provide the date(s), time(s) and time zone you are available for an interview over the next two weeks. You will receive a calendar invite from the US-FM NYO DPP Operations Correspondence mailbox for your interview."},
                      size: "STANDARD",

                      style: "EMPHASIS"
                    )
                  }
                ),
                #"SYSTEM_SYSRULES_paragraphField"(
                  instructions: "Please reach out to the US-FM NYO DPP Operations Correspondence mailbox (us-nyodppopscorr@kpmg.com) if you have any questions. [Please charge your time to 4000003956 - DPP-HR/Operations Responsibilities Phase 30 - Recruiting/onboarding]",
                  characterLimit: 1000,
                  height: "MEDIUM",
                  value: property(ri!nomination,"interviewAvailability",null),
                  saveInto: ri!nomination.interviewAvailability
                )
              }
            )
          }
        ),
        showWhen: ri!nomination.isInterviewAvailabilityRequested = true
      ),
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        labelSize: "SMALL",
        marginBelow: "STANDARD",
        isCollapsible: true,
        contents: #"SYSTEM_SYSRULES_columnsLayout"(
          marginBelow: "STANDARD",
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: #"SYSTEM_SYSRULES_dropdownField_v1"(
                instructions: "Please select your office visit date. [Please charge your time to 4000003956 - DPP-HR/Operations Responsibilities Phase 30 - Recruiting/onboarding]",
                choiceLabels: local!dropdownMenuOptions,
                choiceValues: local!dropdownMenuOptions,
                placeholder: "-- Select a Date --",
                value: property(ri!nomination,"officeVisitAvailability",null),
                saveInto: ri!nomination.officeVisitAvailability,
                validations: if(
                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!nomination.officeVisitAvailability),
                  "",
                  if(
                    contains(local!validDropdownMenuOptions, ri!nomination.officeVisitAvailability),
                    "",
                    "Please select a new office visit date"
                  )
                )
              )
            ),
            #"SYSTEM_SYSRULES_columnLayout"()
          }
        ),
        showWhen:ri!nomination.isOfficeVisitAvailabilityRequested = true
      )
    }
  )
)
